            self.nameUTF8.removeAll(keepingCapacity: true)
            self.nameUTF8.append(contentsOf: other.nameUTF8)
            self.cells.removeAll(keepingCapacity: true)
            self.cells.append(contentsOf: other.cells)
            self.pairs.removeAll(keepingCapacity: true)
            self.pairs.append(contentsOf: other.pairs)
            self.origin = other.origin
            self.hasNote = other.hasNote
            self.noteUTF8.removeAll(keepingCapacity: true)
            self.noteUTF8.append(contentsOf: other.noteUTF8)
            self.reading = other.reading
            switch self.reading {
            case .number:
                self.readingNumber = other.readingNumber

            case .code:
                self.readingCodeUTF8.removeAll(keepingCapacity: true)
                self.readingCodeUTF8.append(contentsOf: other.readingCodeUTF8)

            case .nothing:
                break

            }
            self.labels.removeAll(keepingCapacity: true)
            for index33 in 0..<other.labels.count {
                if index33 == self.__labelsPool.count { self.__labelsPool.append(LabelsItem()) }
                let item33 = self.__labelsPool[index33]
                item33.copy(from: other.labels[index33])
                self.labels.append(item33)
